<?php use Tivoli\Domain\Stay\StayRules as R;?>
<section class="card"><h2>Correct Approved Payroll</h2><p>Original employee, salary revision and payment destination remain fixed. Correct evidenced figures; record any actual top-up separately. A real overpayment stays outstanding.</p>
<form method="post" enctype="multipart/form-data" id="payroll-correction" data-before-cost="<?=(int)$p['cost']?>" data-before-net="<?=(int)$p['net']?>" data-paid="<?=(int)$case['paid']?>" data-confirm="Confirm the exact payroll correction? It will not move money."><?php p_fields('correct');?><label>Correction Type *<select name="type"><option value="components">Approved Payroll Components</option><?php if($case['payments']):?><option value="payment">One Recorded Transfer Amount</option><?php endif?></select></label>
<div data-correction-only="components" class="payroll-grid"><?php foreach(['base'=>'Base Salary','allowance'=>'Allowances','overtime'=>'Overtime','deductions'=>'Reviewed Deductions','employer'=>'Employer Costs'] as $name=>$label)p_input($label.' (GHS)',$name,R::decimal($p[$name]));?></div>
<div data-correction-only="payment" hidden><label>Original Recorded Transfer *<select name="payment_id"><?php foreach($case['payments'] as $payment):?><option value="<?=(int)$payment['id']?>" data-amount="<?=(int)$payment['data']['amount']?>">#<?=(int)$payment['id']?> · <?=access_h(p_money($payment['data']['amount']).' · '.$payment['data']['reference'].' · '.display_date($payment['data']['paid_at']))?> UTC</option><?php endforeach?></select></label><?php p_input('Correct Recorded Transfer Amount (GHS)','amount',R::decimal($case['payments'][0]['data']['amount']??0));p_check('recording_error','This is an evidenced recording error. No money was returned and no actual employee overpayment is being removed.');?></div>
<?php p_text('Correction Reason (Private)','reason',true);p_input('Reviewed Component / Original Transfer Evidence Reference (Private)','evidence_reference');p_text('Employee Statement Note','employee_note');?><label>Supporting File (Optional)<input type="file" name="evidence" accept=".pdf,.png,.jpg,.jpeg"><small>PDF, JPEG or PNG · Maximum 2 MB · Owner Only</small></label><p data-correction-preview role="status" aria-live="polite"></p><?php p_check('verified','I independently verified the original payroll, component or transfer evidence, and every before / after amount.');?><div class="payroll-row"><button>Confirm &amp; Record Correction</button><a href="<?=access_h(p_url(['id'=>$id]))?>#payroll-action">Cancel</a></div></form></section>
